from pathlib import Path
import subprocess,re,difflib,json,hashlib
p=Path('/tmp/atcoder_dijkstra_followup_20261020');binary=p/'mixed_release_gcc'
# Fixed addresses verified from this exact binary's nm -S -C output.
pairs={
 'distance':{'Baseline':(0x405b90,0xa8a),'Candidate':(0x408990,0xa8a)},
 'distance_cold':{'Baseline':(0x401438,0xf1),'Candidate':(0x40187c,0xf1)},
 'path':{'Baseline':(0x40dac0,0xe6c),'Candidate':(0x412dc0,0xe6c)},
}
def names(code):
 def f(m):
  name,variant,args=m.groups();args=args.split(', ')
  expected=3 if name.endswith('BigImpl') else 2
  if variant=='Candidate' and len(args)==expected+1 and args[-1]=='false':args=args[:-1]
  return name+'Variant<'+', '.join(args)+'>'
 code=re.sub(r'(ReinsirkDijkstra(?:BigImpl|Large))(Baseline|Candidate)<([^>]*)>',f,code)
 return code.replace('Baseline','Variant').replace('Candidate','Variant')
results={}
for name,entries in pairs.items():
 rows={}
 for variant,(start,size) in entries.items():
  raw=subprocess.check_output(['objdump','-d','-C','--no-show-raw-insn',f'--start-address={start}',f'--stop-address={start+size}',str(binary)],text=True)
  (p/f'asm_release_{name}_{variant}.txt').write_text(raw)
  lines=[]
  for l in raw.splitlines():
   m=re.match(r'\s*([0-9a-f]+):\s*(.*)',l)
   if not m:continue
   code=names(m.group(2))
   m2=re.match(r'(j\S+|call)\s+([0-9a-f]+)\s+<(.*)>',code)
   if m2:
    op,target,sym=m2.groups();target=int(target,16)
    code=f'{op} local+{target-start:x}' if start<=target<start+size else f'{op} <{sym}>'
   lines.append(code)
  normalized='\n'.join(lines)+'\n'
  (p/f'asm_release_{name}_{variant}_normalized.txt').write_text(normalized)
  rows[variant]={'address':hex(start),'bytes':size,'instructions':len(lines),'normalized_sha256':hashlib.sha256(normalized.encode()).hexdigest(),'normalized':lines}
 diff=list(difflib.unified_diff(rows['Baseline']['normalized'],rows['Candidate']['normalized'],fromfile='Baseline',tofile='Candidate'))
 (p/f'asm_release_{name}_diff.txt').write_text('\n'.join(diff))
 results[name]={'equal_after_normalization':not diff,'functions':{k:{kk:vv for kk,vv in v.items() if kk!='normalized'} for k,v in rows.items()},'diff_lines':diff}
 print(name,results[name]['equal_after_normalization'],{k:(v['bytes'],v['instructions']) for k,v in rows.items()})
 if diff:print('\n'.join(diff[:100]))
output={'binary':str(binary),'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'normalization':'Local branch targets relative to function start; Baseline/Candidate names unified; Candidate extra PruneTerminal=false template argument removed from callee names; all other instruction text unchanged.','comparisons':results}
(p/'asm_release_comparison.json').write_text(json.dumps(output,indent=2)+'\n')

